char t[] = "Science books are fun.";
int L = 0, W = 1, S = 0;
for (int i = 0; t[i]; i++) {
    char c = t[i];
    if (isalpha(c)) L++;
    if (c == ' ') W++;
    if (strchr(".!?", c)) S++;
}
printf("%d %d %d\n", L, W, S);

double l = L * 100.0 / W;
double s = S * 100.0 / W;
double x = 0.0588 * l - 0.296 * s;
x = x - 15.8;
printf("%.2f %d\n", x, (int) (x + 0.5));

char shift(char c, int base, int k) {
    return base + (c - base + k) % 26;
}

char s[] = "Hi, Zed";
for (int i = 0; s[i]; i++) {
    if (isupper(s[i])) {
        s[i] = shift(s[i], 'A', 3);
    } else if (islower(s[i])) {
        s[i] = shift(s[i], 'a', 3);
    }
}
printf("%s\n", s);

char key[] =
    "qwertyuiopasdfghjklzxcvbnm";
char s[] = "Hello";
for (int i = 0; s[i]; i++) {
    if (isupper(s[i])) {
        s[i] = toupper(key[s[i] - 'A']);
    } else if (islower(s[i])) {
        s[i] = tolower(key[s[i] - 'a']);
    }
}
printf("%s\n", s);
